const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Chongqing area
  const chongqing = ee.Geometry.Point([106.5, 29.5]).buffer(50000);

  // Time periods
  const period1_start = '2020-02-10';
  const period1_end = '2020-02-26';
  const period2_start = '2020-04-20';
  const period2_end = '2020-05-13';

  // Load Sentinel-5P NO2 data
  const col1 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select('tropospheric_NO2_column_number_density')
    .filterBounds(chongqing)
    .filterDate(period1_start, period1_end);

  const col2 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select('tropospheric_NO2_column_number_density')
    .filterBounds(chongqing)
    .filterDate(period2_start, period2_end);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Period 1 (Feb 10-25): ${size1} images`);
  console.log(`Period 2 (Apr 20-May 12): ${size2} images`);

  if (size1 === 0 || size2 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // Calculate mean NO2 for each period
  const mean1 = col1.mean();
  const mean2 = col2.mean();

  // Get statistics with pixel count
  const stats1 = mean1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: chongqing,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = mean2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: chongqing,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const val1 = stats1.tropospheric_NO2_column_number_density_mean;
  const count1 = stats1.tropospheric_NO2_column_number_density_count;
  const val2 = stats2.tropospheric_NO2_column_number_density_mean;
  const count2 = stats2.tropospheric_NO2_column_number_density_count;

  console.log(`Feb NO2: ${val1}, Pixels: ${count1}`);
  console.log(`Apr-May NO2: ${val2}, Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  if (val1 === null || val1 === undefined || val2 === null || val2 === undefined ||
      isNaN(val1) || isNaN(val2)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare values (NO2 in mol/m²)
  console.log(`Change: ${((val2 - val1) / val1 * 100).toFixed(2)}%`);

  if (val2 > val1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
